LogStream = {
    init: async function(app, container) {
        container = container || $(".component[name=LogStream]");
        if(typeof signalR === "undefined") {
            $("[name=logConsole]", container).append("<div class='message warn'>SignalR client is not loaded.</div>");
            return;
        }
        await LogStream.connectToLogHub(container);
    },

    connectToLogHub: async function(container) {
        var host = window.location.hostname.split(':')[0];
        await LogStream.connectToHub(container, function(connection) {
            connection.invoke("join", host);
            connection.invoke("ConsoleSend", "info", "Client Connected to Log Stream ", host);
        });
    },

    connectToHub: async function(container, callback) {
        var connection = new signalR.HubConnectionBuilder().withUrl(session.apiRoot + "Hubs/Logs").build();
        connection.on("ConsoleReceive", function(level, message) { LogStream.receiveMessage(container, level, message); });
        await connection.start();
        callback(connection);
    },

    receiveMessage: function(container, level, message) {
        var entry = { Level: (level || "info").toLowerCase(), Timestamp: new Date(), Message: message };
        if(entry.Level == "information") { entry.Level = "info"; }
        if(entry.Level == "warning") { entry.Level = "warn"; }
        var htmlConsole = $(".execConsole > .console", container);
        htmlConsole.append(LogStream.buildMessage(entry));
        if($("input[name=autoScroll]", container).is(":checked")) {
            htmlConsole.scrollTop(htmlConsole.prop("scrollHeight"));
        }
    },

    buildMessage: function(logEntry) {
        var time = new Date(logEntry.Timestamp);
        var encoded = $('<div />').text(logEntry.Message).html();
        return "<div class='message " + logEntry.Level + "'>" +
            "<div class='level'>" + logEntry.Level.toUpperCase() + "</div>" +
            "<div class='time'>" + time.getHours() + ":" + time.getMinutes() + ":" + time.getSeconds() + "</div>" +
            "<pre class='message'>" + encoded + "</pre>" +
            "</div>";
    }
};
